using UnityEngine;using UnityEditor;using System;using System.Linq;using System.Text;
public static class ValidateGroundAlignment {public static string Main(){if(!Application.isPlaying)throw new Exception("Play Mode required");var report=new StringBuilder();var sources=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Models/Pickups/Driveable","Assets/Models/Lawnmower/Driveable","Assets/Models/bicycle/Optimized","Assets/Models/motorcycle-old/Optimized","Assets/Models/3WheelCar/Driveable"}).Select(g=>AssetDatabase.LoadAssetAtPath<GameObject>(AssetDatabase.GUIDToAssetPath(g))).Where(g=>g.GetComponentInChildren<BicycleController>()!=null).Select(g=>g.GetComponentInChildren<BicycleController>()).ToArray();foreach(var source in sources){GameObject floor=null,copy=null;try{
 floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(10000,-.5f,10000);floor.transform.rotation=Quaternion.Euler(-12,0,8);floor.transform.localScale=new Vector3(200,1,200);Vector3 normal=floor.transform.up,point=floor.transform.TransformPoint(new Vector3(0,.5f,0));var path=AssetDatabase.GetAssetPath(source.transform.root.gameObject);copy=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(path),new Vector3(10000,1,10000),Quaternion.identity);var rig=copy.GetComponentInChildren<BicycleController>();rig.SetRidden(true);Physics.SyncTransforms();for(int i=0;i<150;i++){rig.Drive(0,0,true,.02f);Physics.SyncTransforms();}var alignment=rig.GetComponent<VehicleGroundAlignment>();float tiltError=Vector3.Angle(alignment.Pose.up,normal);if(tiltError>1)throw new Exception(source.name+" alignment error="+tiltError);
 var wheels=new System.Collections.Generic.List<Transform>{rig.frontWheel,rig.rearWheel};var pickup=rig.GetComponent<PickupController>();var mower=rig.GetComponent<LawnmowerController>();var trike=rig.GetComponent<TrikeController>();if(pickup){wheels.Add(pickup.frontRightWheel);wheels.Add(pickup.rearRightWheel);}if(mower){wheels.Add(mower.frontRightWheel);wheels.Add(mower.rearRightWheel);}if(trike)wheels.Add(trike.RearRightWheel);
 if(!mower){var start=rig.transform.position;for(int step=0;step<200;step++){rig.Drive(1,0,false,.02f);Physics.SyncTransforms();}if(rig.transform.position.z<start.z+5)throw new Exception(source.name+" cannot drive up slope");for(int step=0;step<150;step++){rig.Drive(0,0,true,.02f);Physics.SyncTransforms();}} string gaps="";foreach(var wheel in wheels){float gap=float.PositiveInfinity;foreach(var mf in wheel.GetComponentsInChildren<MeshFilter>()){if(mf.name.Contains("LOD1")||mf.name.Contains("LOD2"))continue;foreach(var v in mf.sharedMesh.vertices)gap=Mathf.Min(gap,Vector3.Dot(mf.transform.TransformPoint(v)-point,normal));}gaps+=gap.ToString("F3")+",";if(gap<-.04f||gap>.08f)throw new Exception(source.name+" wheel "+wheel.name+" tire/ground gap="+gap);}
 report.AppendLine(source.name+": PASS tilt error="+tiltError.ToString("F3")+" tire gaps="+gaps);
 }finally{if(copy)UnityEngine.Object.DestroyImmediate(copy);if(floor)UnityEngine.Object.DestroyImmediate(floor);}}System.IO.File.WriteAllText("output/Pickups/ground-alignment-validation.txt",report.ToString());return report.ToString();}}


